SELECT MIN(started_at) AS first_started_at, MAX(ended_at) AS last_ended_at
FROM time_log
WHERE workspace_id = #{workspaceId} AND task_id = #{taskId}

SELECT COALESCE(SUM(minutes), 0) FROM time_log
WHERE workspace_id = #{workspaceId} AND user_id = #{userId}
  AND ended_at IS NOT NULL AND started_at >= #{from}

SELECT COALESCE(SUM(minutes), 0) FROM time_log
WHERE workspace_id = #{workspaceId}
  AND ended_at IS NOT NULL AND started_at >= #{from}

SELECT COALESCE(SUM(minutes), 0) FROM time_log
WHERE workspace_id = #{workspaceId}
  AND ended_at IS NOT NULL
  AND started_at >= #{from} AND started_at < #{to}

SELECT id, task_id, workspace_id, user_id, started_at, ended_at, minutes
FROM time_log
WHERE workspace_id = #{workspaceId}
  AND started_at >= #{from} AND started_at < #{to}
